/* ============================================================
 * Bit I/O
 * ============================================================ */
typedef struct {
    const uint8_t *buf;
    int buf_len;
    int bit_pos;
} BitReader;

static void br_init(BitReader *br, const uint8_t *buf, int len) {
    br->buf = buf;
    br->buf_len = len;
    br->bit_pos = 0;
}

static uint32_t br_read(BitReader *br, int n) {
    uint32_t result = 0;
    for (int i = 0; i < n; i++) {
        int byte_idx = br->bit_pos >> 3;
        int bit_idx = 7 - (br->bit_pos & 7);
        int bit = (br->buf[byte_idx] >> bit_idx) & 1;
        result = (result << 1) | bit;
        br->bit_pos++;
    }
    return result;
}

static int32_t br_read_signed(BitReader *br, int n) {
    uint32_t val = br_read(br, n);
    if (val >= (uint32_t)(1 << (n-1)))
        val -= (uint32_t)(1 << n);
    return (int32_t)val;
}

static int32_t br_read_rice_signed(BitReader *br, int k) {
    uint32_t q = 0;
    while (br_read(br, 1) == 0) q++;
    uint32_t r = br_read(br, k);
    uint32_t val = (q << k) | r;
    /* un-zigzag */
    if (val & 1)
        return -(int32_t)(val >> 1) - 1;
    else
        return (int32_t)(val >> 1);
}

typedef struct {
