    uint8_t expected_crc8 = crc8(br->buf + start_bit/8, header_bytes);
    uint32_t actual_crc8 = br_read(br, 8);
    /* Note: we skip CRC verification for now */

    /* Decode subframes */
    int32_t *channel_data = calloc(channels * block_size, sizeof(int32_t));

    for (int ch = 0; ch < channels; ch++) {
        int32_t *buf = channel_data + ch * block_size;
        int ch_bps = bps;
        if (left_side && ch == 1) ch_bps++;
        if (right_side && ch == 0) ch_bps++;
        if (mid_side && ch == 1) ch_bps++;

        uint32_t sf_header = br_read(br, 8);
        uint32_t sf_type = (sf_header >> 1) & 0x3f;
        int wasted = sf_header & 1;
        if (wasted) {
            int w = 1;
            while (br_read(br, 1) == 0) w++;
            /* wasted bits unshift done below */
        }

        if (sf_type == 0) {
            /* CONSTANT */
            int32_t val = br_read_signed(br, ch_bps);
            for (int i = 0; i < block_size; i++) buf[i] = val;
        } else if (sf_type == 1) {
            /* VERBATIM */
            for (int i = 0; i < block_size; i++)
                buf[i] = br_read_signed(br, ch_bps);
        } else if ((sf_type >= 8) && (sf_type <= 12)) {
            /* FIXED predictor */
            int order = sf_type - 8;
            for (int i = 0; i < order; i++)
                buf[i] = br_read_signed(br, ch_bps);

            /* Read residuals */
            uint32_t method = br_read(br, 2);
            uint32_t partition_order = br_read(br, 4);
            int n_partitions = 1 << partition_order;
            int n_residuals = block_size - order;
            int ri = order;

            for (int p = 0; p < n_partitions; p++) {
                int param;
                if (method == 0) {
                    param = (int)br_read(br, 4);
                    if (param == 15) { /* escape code */
                        int raw_bits = (int)br_read(br, 5);
                        int n = (p == 0) ? (block_size / n_partitions - order) : (block_size / n_partitions);
                        for (int i = 0; i < n; i++) buf[ri++] = br_read_signed(br, raw_bits);
                        continue;
                    }
                } else {
                    param = (int)br_read(br, 5);
                    if (param == 31) { /* escape code */
                        int raw_bits = (int)br_read(br, 5);
                        int n = (p == 0) ? (block_size / n_partitions - order) : (block_size / n_partitions);
                        for (int i = 0; i < n; i++) buf[ri++] = br_read_signed(br, raw_bits);
                        continue;
                    }
                }
                int n = (p == 0) ? (block_size / n_partitions - order) : (block_size / n_partitions);
                for (int i = 0; i < n; i++)
                    buf[ri++] = br_read_rice_signed(br, param);
            }

            /* Restore from residuals using fixed predictor */
            switch (order) {
                case 0: break;
                case 1: for (int i=1;i<block_size;i++) buf[i]+=buf[i-1]; break;
                case 2: for (int i=2;i<block_size;i++) buf[i]+=2*buf[i-1]-buf[i-2]; break;
                case 3: for (int i=3;i<block_size;i++) buf[i]+=3*buf[i-1]-3*buf[i-2]+buf[i-3]; break;
                case 4: for (int i=4;i<block_size;i++) buf[i]+=4*buf[i-1]-6*buf[i-2]+4*buf[i-3]-buf[i-4]; break;
            }
        } else if (sf_type >= 32) {
            /* LPC */
            int order = (sf_type & 0x1f) + 1;
            for (int i = 0; i < order; i++)
                buf[i] = br_read_signed(br, ch_bps);

            int qlp_precision = (int)br_read(br, 4) + 1;
            int qlp_shift = br_read_signed(br, 5);
            int32_t qlp[32];
            for (int i = 0; i < order; i++)
                qlp[i] = br_read_signed(br, qlp_precision);

            /* Read residuals */
            uint32_t method = br_read(br, 2);
            uint32_t partition_order = br_read(br, 4);
            int n_partitions = 1 << partition_order;
            int ri = order;

            for (int p = 0; p < n_partitions; p++) {
                int param;
                if (method == 0) {
                    param = (int)br_read(br, 4);
                    if (param == 15) {
                        int raw_bits = (int)br_read(br, 5);
                        int n = (p == 0) ? (block_size / n_partitions - order) : (block_size / n_partitions);
                        for (int i = 0; i < n; i++) buf[ri++] = br_read_signed(br, raw_bits);
                        continue;
                    }
                } else {
                    param = (int)br_read(br, 5);
                    if (param == 31) {
                        int raw_bits = (int)br_read(br, 5);
                        int n = (p == 0) ? (block_size / n_partitions - order) : (block_size / n_partitions);
                        for (int i = 0; i < n; i++) buf[ri++] = br_read_signed(br, raw_bits);
                        continue;
                    }
                }
                int n = (p == 0) ? (block_size / n_partitions - order) : (block_size / n_partitions);
                for (int i = 0; i < n; i++)
                    buf[ri++] = br_read_rice_signed(br, param);
            }

            /* Restore from LPC residuals */
            for (int i = order; i < block_size; i++) {
                int64_t pred = 0;
                for (int j = 0; j < order; j++)
                    pred += (int64_t)qlp[j] * buf[i-1-j];
                buf[i] += (int32_t)(pred >> qlp_shift);
            }
        } else {
            free(channel_data);
            return -1;
        }
    }

    /* Byte-align */
    int align = br->bit_pos & 7;
    if (align) br->bit_pos += 8 - align;

    /* CRC-16 footer */
    int frame_bytes = (br->bit_pos - start_bit) / 8;
    uint16_t frame_crc16 = crc16(br->buf + start_bit/8, frame_bytes);
    uint32_t stored_crc16 = br_read(br, 16);
    /* skip verification */

    /* Decorrelate channels */
    if (left_side) {
        /* left = left, right = left - side */
        int32_t *left = channel_data;
        int32_t *side = channel_data + block_size;
        for (int i = 0; i < block_size; i++)
            side[i] = left[i] - side[i];
    } else if (right_side) {
        /* right = right, left = side + right */
        int32_t *side = channel_data;
        int32_t *right = channel_data + block_size;
        for (int i = 0; i < block_size; i++)
            side[i] = side[i] + right[i];
    } else if (mid_side) {
        /* mid = (left+right)/2, side = left-right */
        int32_t *mid = channel_data;
        int32_t *side = channel_data + block_size;
        for (int i = 0; i < block_size; i++) {
            int32_t m = mid[i];
            int32_t s = side[i];
            int32_t r = m - (s >> 1);
            mid[i] = r + s;
            side[i] = r;
        }
    }

    /* Output interleaved samples, clipped to bps range */
    int shift = 32 - bps;
    int32_t clip_max = (1 << (bps-1)) - 1;
    int32_t clip_min = -(1 << (bps-1));
    for (int i = 0; i < block_size; i++) {
        for (int ch = 0; ch < channels; ch++) {
            int32_t s = channel_data[ch * block_size + i];
            if (s > clip_max) s = clip_max;
            if (s < clip_min) s = clip_min;
            out_samples[i * channels + ch] = (int16_t)s;
        }
    }

    free(channel_data);
    return block_size;
}

static AudioBuf* flac_decode(const char *filename) {
    FILE *f = fopen(filename, "rb");
    if (!f) { fprintf(stderr, "Cannot open %s\n", filename); return NULL; }

    fseek(f, 0, SEEK_END);
    long file_size = ftell(f);
    fseek(f, 0, SEEK_SET);

    uint8_t *data = malloc(file_size);
    fread(data, 1, file_size, f);
    fclose(f);

    if (memcmp(data, "fLaC", 4) != 0) {
        free(data); fprintf(stderr, "Not a FLAC file\n"); return NULL;
    }

    /* Parse metadata */
    int pos = 4;
    int sr = 44100, channels = 1, bps = 16;
    int total_samples = 0;
    uint8_t md5_stored[16] = {0};
    int min_block = 4096, max_block = 4096;

    while (pos < file_size) {
        uint8_t blk_header = data[pos];
        int is_last = (blk_header & 0x80) != 0;
        int blk_type = blk_header & 0x7f;
        int blk_size = (data[pos+1] << 16) | (data[pos+2] << 8) | data[pos+3];

        if (blk_type == 0) { /* STREAMINFO */
            uint8_t *si = data + pos + 4;
            min_block = (si[0] << 8) | si[1];
            max_block = (si[2] << 8) | si[3];
            uint64_t info = 0;
            for (int i = 10; i < 18; i++) info = (info << 8) | si[i];
            sr = (int)((info >> 44) & 0xFFFFF);
            channels = (int)((info >> 41) & 0x7) + 1;
            bps = (int)((info >> 36) & 0x1F) + 1;
            total_samples = (int)(info & 0xFFFFFFFFF);
            memcpy(md5_stored, si + 18, 16);
        }

        pos += 4 + blk_size;
        if (is_last) break;
    }

    /* Allocate output buffer */
    if (total_samples <= 0) total_samples = (int)(file_size * 8 / (bps * channels) / 2); /* estimate */
    AudioBuf *ab = audio_alloc(total_samples + max_block, sr, channels, bps);
    int n_out = 0;

    /* Decode frames */
    BitReader br;
    br_init(&br, data, file_size);
    br.bit_pos = pos * 8;

    int32_t tmp[65536];
    while (br.bit_pos < file_size * 8 - 16) {
        /* Look for sync */
        int sync_start = br.bit_pos;

        /* Peek at next 15 bits */
        if (br.bit_pos + 15 > file_size * 8) break;

        int n = flac_decode_frame(&br, ab->samples + n_out, total_samples - n_out, 
                                   sr, channels, bps);
        if (n < 0) {
            /* Skip a byte and try again */
            br.bit_pos = sync_start + 8;
            if (n_out >= total_samples) break;
            continue;
        }
        n_out += n;
        if (n_out >= total_samples) break;
    }

    ab->n_samples = n_out;
    memcpy(ab->md5, md5_stored, 16);
    free(data);
    return ab;
}

