#define FLAC_MAX_LPC_ORDER 12
#define FLAC_DEFAULT_BLOCK_SIZE 4608

/* Compute autocorrelation without windowing */
static void compute_autocorr(const int32_t *x, int n, double *r, int max_lag) {
    for (int lag = 0; lag <= max_lag; lag++) {
        double s = 0;
        for (int i = lag; i < n; i++)
            s += (double)x[i] * (double)x[i - lag];
        r[lag] = s;
    }
}

/* Levinson-Durbin recursion */
/* Returns LPC order actually computed */
static int levinson_durbin(const double *r, int order, double *lpc) {
    double a[FLAC_MAX_LPC_ORDER + 1] = {0};
    double E = r[0];

    if (E <= 0) return 0;

    for (int m = 1; m <= order; m++) {
        double num = r[m];
        for (int j = 1; j < m; j++)
            num += a[j] * r[m - j];
        double k = -num / E;

        double new_a[FLAC_MAX_LPC_ORDER + 1];
        new_a[m] = k;
        for (int j = 1; j < m; j++)
            new_a[j] = a[j] + k * a[m - j];
        for (int j = 1; j <= m; j++)
            a[j] = new_a[j];

        E *= (1.0 - k * k);
        if (E <= 0) { order = m - 1; break; }
    }

    /* lpc[i] = -a[i+1] (FLAC convention: pred = sum(lpc[i]*s[n-1-i])) */
    for (int i = 0; i < order; i++)
        lpc[i] = -a[i + 1];

    return order;
}

/* Quantize LPC coefficients */
static int quantize_lpc(const double *lpc, int order, int precision, 
                         int32_t *qlp, int *shift_out) {
    if (order <= 0) return 0;

    double max_abs = 0;
    for (int i = 0; i < order; i++) {
        double a = lpc[i] < 0 ? -lpc[i] : lpc[i];
        if (a > max_abs) max_abs = a;
    }

    if (max_abs <= 0) {
        for (int i = 0; i < order; i++) qlp[i] = 0;
        *shift_out = 0;
        return order;
    }

    int shift = (int)floor(log2((double)(1 << (precision - 1)) / max_abs));
    if (shift < 0) shift = 0;
    if (shift > 15) shift = 15;

    double scale = (double)(1 << shift);
    for (int i = 0; i < order; i++) {
        qlp[i] = (int32_t)round(lpc[i] * scale);
