static int find_rice_param(const int32_t *residuals, int n) {
    /* Find Rice parameter that minimizes coded bits */
    /* For Rice code with parameter k: bits = n*(k+1) + sum(|r|)*2/2^k */

    /* Compute sum of absolute values */
    uint64_t sum_abs = 0;
    for (int i = 0; i < n; i++)
        sum_abs += (uint64_t)(residuals[i] < 0 ? -residuals[i] : residuals[i]);

