/* Encode one FLAC frame into a byte buffer, return size */
static int encode_flac_frame(const int16_t *samples, int block_size, int channels,
                               int sample_rate, int bps, uint32_t frame_num,
                               uint8_t *out_buf, int out_max) {
    static int crc_inited = 0;
    if (!crc_inited) { crc8_init(); crc16_init(); crc_inited = 1; }

    BitWriter bw;
    bw_init(&bw, out_buf, out_max);

    /* === Frame header === */
    /* sync + reserved + blocking_strategy */
    bw_write(&bw, 0xFFF8, 16);

    /* Block size code: 7 = 16-bit value - 1 at end of header */
    bw_write(&bw, 7, 4);  /* block_size_code = 7 */

    /* Sample rate code: 9 = 44100 Hz (hardcoded for now) */
    int sr_code = 0;
    int sr_table[] = {0,88200,176400,192000,8000,16000,22050,24000,32000,44100,48000,96000};
    for (int i = 1; i <= 11; i++) {
        if (sr_table[i] == sample_rate) { sr_code = i; break; }
    }
    if (sr_code == 0) sr_code = 13;  /* 16-bit Hz */
    bw_write(&bw, sr_code, 4);

    /* Channel assignment: 0 = mono, 1 = stereo, etc. */
    if (channels == 1) bw_write(&bw, 0, 4);
    else bw_write(&bw, channels - 1, 4);

    /* Sample size code */
    int bps_code = 0;
    int bps_table[] = {0,8,12,0,16,20,24,32};
    for (int i = 1; i <= 7; i++) {
        if (bps_table[i] == bps) { bps_code = i; break; }
    }
    bw_write(&bw, bps_code, 3);
    bw_write(&bw, 0, 1); /* reserved */

    /* Frame number (UTF-8 coded) */
    /* For small frame numbers: 1 byte */
    if (frame_num < 128) {
        bw_write(&bw, frame_num, 8);
    } else if (frame_num < 0x800) {
        bw_write(&bw, 0xC0 | (frame_num >> 6), 8);
        bw_write(&bw, 0x80 | (frame_num & 0x3F), 8);
    } else {
        /* 3-byte UTF-8 */
        bw_write(&bw, 0xE0 | (frame_num >> 12), 8);
        bw_write(&bw, 0x80 | ((frame_num >> 6) & 0x3F), 8);
        bw_write(&bw, 0x80 | (frame_num & 0x3F), 8);
    }

    /* Block size - 1 (16-bit) */
    bw_write(&bw, block_size - 1, 16);

    /* Sample rate if code == 13 */
    if (sr_code == 13) bw_write(&bw, sample_rate, 16);

    /* CRC-8 of header so far */
    int header_bytes = bw_bytes(&bw);
    uint8_t hdr_crc = crc8(out_buf, header_bytes);
    bw_write(&bw, hdr_crc, 8);

    /* === Subframes === */
    for (int ch = 0; ch < channels; ch++) {
        /* Convert to int32 for LPC computation */
        int32_t int_samples[65536];
        for (int i = 0; i < block_size; i++)
            int_samples[i] = samples[i * channels + ch];

        double lpc[FLAC_MAX_LPC_ORDER + 1];
        int32_t qlp[FLAC_MAX_LPC_ORDER + 1];
        int shift;

        int order = choose_order(int_samples, block_size, bps, FLAC_MAX_LPC_ORDER,
                                  lpc, qlp, &shift);

        int32_t residuals[65536];

        if (order == 0) {
            /* CONSTANT subframe */
            bw_write(&bw, 0x00, 8);  /* type = CONSTANT, no wasted bits */
            bw_write_signed(&bw, int_samples[0], bps);
        } else if (order < 0) {
            /* FIXED predictor */
            int fixed_order = -order - 1;
            bw_write(&bw, (8 + fixed_order) << 1, 8);

            /* Warmup samples */
            for (int i = 0; i < fixed_order; i++)
                bw_write_signed(&bw, int_samples[i], bps);

            /* Compute fixed residuals */
            int32_t tmp[65536];
            memcpy(tmp, int_samples, block_size * sizeof(int32_t));
            for (int d = 0; d < fixed_order; d++) {
                for (int i = block_size - 1; i >= d + 1; i--)
                    tmp[i] -= tmp[i-1];
            }
            int n_res = block_size - fixed_order;
            for (int i = 0; i < n_res; i++)
                residuals[i] = tmp[fixed_order + i];

            int rice_param = find_rice_param(residuals, n_res);
            bw_write(&bw, 0, 2);  /* method = Rice */
            bw_write(&bw, 0, 4);  /* partition_order = 0 */
            bw_write(&bw, rice_param, 4);
            for (int i = 0; i < n_res; i++)
                write_rice_signed(&bw, residuals[i], rice_param);
        } else {
            /* LPC subframe */
            bw_write(&bw, ((32 + order - 1) << 1), 8);

            /* Warmup samples */
            for (int i = 0; i < order; i++)
                bw_write_signed(&bw, int_samples[i], bps);

            /* QLP precision - 1 (4 bits) */
            bw_write(&bw, 14, 4);  /* precision = 15 */

            /* QLP shift (5 bits, signed) */
            bw_write_signed(&bw, shift, 5);

            /* QLP coefficients */
            for (int i = 0; i < order; i++)
                bw_write_signed(&bw, qlp[i], 15);

            /* Residuals */
            compute_residuals(int_samples, block_size, qlp, order, shift, residuals);

            int n_res = block_size - order;
            int rice_param = find_rice_param(residuals, n_res);
            bw_write(&bw, 0, 2);  /* method = Rice */
            bw_write(&bw, 0, 4);  /* partition_order = 0 */
            bw_write(&bw, rice_param, 4);
            for (int i = 0; i < n_res; i++)
                write_rice_signed(&bw, residuals[i], rice_param);
        }
    }

    /* Byte-align */
    int cur_bits = bw.bit_pos & 7;
    if (cur_bits) bw_write(&bw, 0, 8 - cur_bits);

    /* CRC-16 footer */
    int frame_bytes = bw_bytes(&bw);
    uint16_t frame_crc = crc16(out_buf, frame_bytes);
    bw_write(&bw, frame_crc, 16);

    return bw_bytes(&bw);
}

