/* ============================================================
 * FLAC Encoder
 * Uses standard Levinson-Durbin LPC algorithm
 * ============================================================ */

#define FLAC_MAX_LPC_ORDER 12
#define FLAC_DEFAULT_BLOCK_SIZE 4608

/* Compute autocorrelation without windowing */
static void compute_autocorr(const int32_t *x, int n, double *r, int max_lag) {
    for (int lag = 0; lag <= max_lag; lag++) {
        double s = 0;
        for (int i = lag; i < n; i++)
            s += (double)x[i] * (double)x[i - lag];
        r[lag] = s;
    }
}

/* Levinson-Durbin recursion */
/* Returns LPC order actually computed */
static int levinson_durbin(const double *r, int order, double *lpc) {
    double a[FLAC_MAX_LPC_ORDER + 1] = {0};
    double E = r[0];

    if (E <= 0) return 0;

    for (int m = 1; m <= order; m++) {
        double num = r[m];
        for (int j = 1; j < m; j++)
            num += a[j] * r[m - j];
        double k = -num / E;

        double new_a[FLAC_MAX_LPC_ORDER + 1];
        new_a[m] = k;
        for (int j = 1; j < m; j++)
            new_a[j] = a[j] + k * a[m - j];
        for (int j = 1; j <= m; j++)
            a[j] = new_a[j];

        E *= (1.0 - k * k);
        if (E <= 0) { order = m - 1; break; }
    }

    /* lpc[i] = -a[i+1] (FLAC convention: pred = sum(lpc[i]*s[n-1-i])) */
    for (int i = 0; i < order; i++)
        lpc[i] = -a[i + 1];

    return order;
}

/* Quantize LPC coefficients */
static int quantize_lpc(const double *lpc, int order, int precision, 
                         int32_t *qlp, int *shift_out) {
    if (order <= 0) return 0;

    double max_abs = 0;
    for (int i = 0; i < order; i++) {
        double a = lpc[i] < 0 ? -lpc[i] : lpc[i];
        if (a > max_abs) max_abs = a;
    }

    if (max_abs <= 0) {
        for (int i = 0; i < order; i++) qlp[i] = 0;
        *shift_out = 0;
        return order;
    }

    int shift = (int)floor(log2((double)(1 << (precision - 1)) / max_abs));
    if (shift < 0) shift = 0;
    if (shift > 15) shift = 15;

    double scale = (double)(1 << shift);
    for (int i = 0; i < order; i++) {
        qlp[i] = (int32_t)round(lpc[i] * scale);
        /* Clip to precision bits */
        int32_t max_val = (1 << (precision - 1)) - 1;
        int32_t min_val = -(1 << (precision - 1));
        if (qlp[i] > max_val) qlp[i] = max_val;
        if (qlp[i] < min_val) qlp[i] = min_val;
    }

    *shift_out = shift;
    return order;
}

/* Find optimal Rice parameter for a set of residuals */
static int find_rice_param(const int32_t *residuals, int n) {
    /* Find Rice parameter that minimizes coded bits */
    /* For Rice code with parameter k: bits = n*(k+1) + sum(|r|)*2/2^k */

    /* Compute sum of absolute values */
    uint64_t sum_abs = 0;
    for (int i = 0; i < n; i++)
        sum_abs += (uint64_t)(residuals[i] < 0 ? -residuals[i] : residuals[i]);

    /* Find k that minimizes bits */
    int best_k = 0;
    uint64_t best_bits = UINT64_MAX;
    for (int k = 0; k < 14; k++) {
        /* Expected bits: n*(k+1) + 2*sum_abs / 2^k */
        uint64_t bits = (uint64_t)n * (k + 1) + 2 * sum_abs / (1ULL << k);
        if (bits < best_bits) {
            best_bits = bits;
            best_k = k;
        }
    }
    return best_k;
}

/* Write Rice-coded signed integer */
static void write_rice_signed(BitWriter *bw, int32_t val, int k) {
    /* Zigzag encode */
    uint32_t uval = (val >= 0) ? (uint32_t)(val << 1) : (uint32_t)((-val - 1) << 1) | 1;
    uint32_t q = uval >> k;
    uint32_t r = uval & ((1u << k) - 1);
    /* Unary code for q */
    for (uint32_t i = 0; i < q; i++) bw_write(bw, 0, 1);
    bw_write(bw, 1, 1);
    /* Binary code for r */
    if (k > 0) bw_write(bw, r, k);
}

/* Compute residuals given LPC coefficients */
static void compute_residuals(const int32_t *samples, int n, 
                               const int32_t *qlp, int order, int shift,
                               int32_t *residuals) {
    for (int i = order; i < n; i++) {
        int64_t pred = 0;
        for (int j = 0; j < order; j++)
            pred += (int64_t)qlp[j] * samples[i - 1 - j];
        residuals[i - order] = samples[i] - (int32_t)(pred >> shift);
    }
}

/* Choose best predictor order using entropy estimate */
static int choose_order(const int32_t *samples, int n, int bps, int max_order,
                         double *best_lpc, int32_t *best_qlp, int *best_shift) {
    if (n <= max_order) max_order = n - 1;
    if (max_order <= 0) max_order = 1;

    double r[FLAC_MAX_LPC_ORDER + 2];
    compute_autocorr(samples, n, r, max_order);

    if (r[0] <= 0) {
        /* Silence: use CONSTANT predictor (handled separately) */
        return 0;
    }

    double lpc[FLAC_MAX_LPC_ORDER + 1];
    int32_t qlp[FLAC_MAX_LPC_ORDER + 1];
    int32_t residuals[65536];
    int shift;
    int precision = 15;

    int best_order = 2;
    double best_entropy = 1e30;

    /* Try LPC orders 1 to max_order */
    for (int order = 1; order <= max_order; order++) {
        double order_r[FLAC_MAX_LPC_ORDER + 2];
        for (int k = 0; k <= order; k++) order_r[k] = r[k];

        int actual_order = levinson_durbin(order_r, order, lpc);
        if (actual_order != order) continue;

        quantize_lpc(lpc, order, precision, qlp, &shift);

        int n_residuals = n - order;
        if (n_residuals <= 0) continue;

        compute_residuals(samples, n, qlp, order, shift, residuals);

        /* Compute entropy estimate (bits per sample) */
        uint64_t sum_abs = 0;
        for (int i = 0; i < n_residuals; i++)
            sum_abs += (uint64_t)(residuals[i] < 0 ? -residuals[i] : residuals[i]);

        /* Approximate entropy: log2(2*sum_abs/n + 1) */
        double mean_abs = (double)sum_abs / n_residuals;
        double entropy = log2(2.0 * mean_abs + 1.0) + (double)order * bps / n;

        if (entropy < best_entropy) {
            best_entropy = entropy;
            best_order = order;
            memcpy(best_lpc, lpc, order * sizeof(double));
            memcpy(best_qlp, qlp, order * sizeof(int32_t));
            *best_shift = shift;
        }
    }

    /* Also try FIXED predictors */
    int32_t fixed_qlp_table[5][4] = {
        {},
        {1},
        {2, -1},
        {3, -3, 1},
        {4, -6, 4, -1}
    };
    for (int order = 0; order <= 4 && order <= n; order++) {
        int n_residuals = n - order;
        if (n_residuals <= 0) continue;

        /* Compute fixed residuals */
        int32_t *fixed_res = residuals;
        /* Store samples first to compute differences */
        int32_t tmp[65536];
        memcpy(tmp, samples, n * sizeof(int32_t));
        for (int d = 0; d < order; d++) {
            for (int i = n - 1; i >= d + 1; i--)
                tmp[i] -= tmp[i-1];
        }
        for (int i = 0; i < n_residuals; i++)
            fixed_res[i] = tmp[order + i];

        uint64_t sum_abs = 0;
        for (int i = 0; i < n_residuals; i++)
            sum_abs += (uint64_t)(fixed_res[i] < 0 ? -fixed_res[i] : fixed_res[i]);

        double mean_abs = (double)sum_abs / n_residuals;
        double entropy = log2(2.0 * mean_abs + 1.0) + (double)order * bps / n;

        /* Bias towards simpler predictors */
        entropy += 0.01;

        if (entropy < best_entropy) {
            best_entropy = entropy;
            best_order = -(order + 1);  /* Negative = fixed */
        }
    }

    return best_order;
}

