/* FLAC encoder main function */
static int flac_encode(const char *filename, const AudioBuf *ab,
                        const char *muxer_version, const char *codec_version) {
    static int crc_inited = 0;
    if (!crc_inited) { crc8_init(); crc16_init(); crc_inited = 1; }

    const char *lavf = muxer_version ? muxer_version : LAVF_VERSION;
    const char *lavc = codec_version ? codec_version : LAVC_VERSION;

    int block_size = FLAC_DEFAULT_BLOCK_SIZE;
    int n_frames = (ab->n_samples + block_size - 1) / block_size;
    int channels = ab->channels;
    int bps = ab->bps;
    int sr = ab->sample_rate;

    /* Compute MD5 of raw audio */
    uint8_t md5[16];
    compute_md5(ab->samples, ab->n_samples * channels, md5);

    /* Encode all frames first to find min/max frame size */
    uint8_t **frame_bufs = calloc(n_frames, sizeof(uint8_t*));
    int *frame_sizes = calloc(n_frames, sizeof(int));
    int total_audio_bytes = 0;
    int min_frame = INT32_MAX, max_frame = 0;

    for (int fi = 0; fi < n_frames; fi++) {
        int start = fi * block_size;
        int this_block = block_size;
        if (start + this_block > ab->n_samples)
            this_block = ab->n_samples - start;

        frame_bufs[fi] = malloc(this_block * channels * bps / 8 * 4 + 1024);
        int sz = encode_flac_frame(ab->samples + start * channels, this_block,
                                    channels, sr, bps, fi,
                                    frame_bufs[fi], this_block * channels * bps / 8 * 4 + 1024);
        frame_sizes[fi] = sz;
        total_audio_bytes += sz;
        if (sz < min_frame) min_frame = sz;
        if (sz > max_frame) max_frame = sz;
    }

    /* Build STREAMINFO block */
    uint8_t streaminfo[34] = {0};
    /* min_block_size */
    streaminfo[0] = (block_size >> 8) & 0xff;
    streaminfo[1] = block_size & 0xff;
    /* max_block_size */
    streaminfo[2] = (block_size >> 8) & 0xff;
    streaminfo[3] = block_size & 0xff;
    /* min_frame_size (24-bit) */
    streaminfo[4] = (min_frame >> 16) & 0xff;
    streaminfo[5] = (min_frame >> 8) & 0xff;
    streaminfo[6] = min_frame & 0xff;
    /* max_frame_size (24-bit) */
    streaminfo[7] = (max_frame >> 16) & 0xff;
    streaminfo[8] = (max_frame >> 8) & 0xff;
    streaminfo[9] = max_frame & 0xff;
    /* sample_rate(20) | channels-1(3) | bps-1(5) | total_samples(36) */
