    if (strcasecmp(ext, "wav") == 0) return "wav";
    if (strcasecmp(ext, "wave") == 0) return "wav";
    return NULL;
}

/* Format duration as HH:MM:SS.SS */
static void format_duration(double secs, char *buf, int buflen) {
    int h = (int)(secs / 3600);
    int m = (int)((secs - h*3600) / 60);
    double s = secs - h*3600 - m*60;
    snprintf(buf, buflen, "%02d:%02d:%05.2f", h, m, s);
}

