    fprintf(stderr, "-filters            show available filters\n");
    fprintf(stderr, "-pix_fmts           show available pixel formats\n");
    fprintf(stderr, "-layouts            show standard channel layouts\n");
    fprintf(stderr, "-sample_fmts        show available audio sample formats\n\n");
    fprintf(stderr, "Global options (affect whole program instead of just one file):\n");
    fprintf(stderr, "-v <loglevel>       set logging level\n");
    fprintf(stderr, "-y                  overwrite output files\n");
    fprintf(stderr, "-n                  never overwrite output files\n");
    fprintf(stderr, "-print_graphs       print execution graph data to stderr\n");
    fprintf(stderr, "-print_graphs_file <filename>  write execution graph data to the specified file\n");
    fprintf(stderr, "-print_graphs_format <format>  set the output printing format (available formats are: default, compact, csv, flat, ini, json, xml, mermaid, mermaidhtml)\n");
    fprintf(stderr, "-stats              print progress report during encoding\n\n");
    fprintf(stderr, "Per-file options (input and output):\n");
    fprintf(stderr, "-f <fmt>            force container format (auto-detected otherwise)\n");
    fprintf(stderr, "-t <duration>       stop transcoding after specified duration\n");
    fprintf(stderr, "-to <time_stop>     stop transcoding after specified time is reached\n");
}

static void print_license(void) {
    print_version_banner();
    fprintf(stderr, "ffmpeg is free software; you can redistribute it and/or\n");
