}

/* Detect file format from extension */
static const char* detect_format(const char *filename) {
    const char *ext = strrchr(filename, '.');
    if (!ext) return NULL;
    ext++;
    if (strcasecmp(ext, "flac") == 0) return "flac";
    if (strcasecmp(ext, "wav") == 0) return "wav";
    if (strcasecmp(ext, "wave") == 0) return "wav";
    return NULL;
}

/* Format duration as HH:MM:SS.SS */
static void format_duration(double secs, char *buf, int buflen) {
    int h = (int)(secs / 3600);
    int m = (int)((secs - h*3600) / 60);
    double s = secs - h*3600 - m*60;
    snprintf(buf, buflen, "%02d:%02d:%05.2f", h, m, s);
}

/* Format size in KiB */
static void format_size_kib(int bytes, char *buf, int buflen) {
    snprintf(buf, buflen, "%9dKiB", (bytes + 512) / 1024);
}

static int do_convert(const Options *opts) {
    const char *in_fmt = detect_format(opts->input_file);
    const char *out_fmt = detect_format(opts->output_file);

    if (!in_fmt) {
        fprintf(stderr, "Cannot detect input format for %s\n", opts->input_file);
        return 1;
    }
    if (!out_fmt) {
        fprintf(stderr, "Cannot detect output format for %s\n", opts->output_file);
        return 1;
    }

    /* Check if output exists */
    if (!opts->overwrite && !opts->no_overwrite) {
        FILE *test = fopen(opts->output_file, "rb");
        if (test) {
            fclose(test);
            fprintf(stderr, "File '%s' already exists. Overwrite? [y/N] ", opts->output_file);
            char c = getchar();
            if (c != 'y' && c != 'Y') {
                fprintf(stderr, "Not overwriting - exiting\n");
                return 1;
            }
        }
    }

    print_version_banner();

    /* Decode input */
    AudioBuf *ab = NULL;

    if (strcmp(in_fmt, "flac") == 0) {
        ab = flac_decode(opts->input_file);
        if (!ab) return 1;

        double duration = (double)ab->n_samples / ab->sample_rate;
        int bitrate = (int)(9541 * 8.0 / duration / 1000);  /* approximate */

        fprintf(stderr, "Input #0, flac, from '%s':\n", opts->input_file);
        fprintf(stderr, "  Metadata:\n");
        fprintf(stderr, "    encoder         : %s\n", LAVF_VERSION);

        char dur_str[64];
        format_duration(duration, dur_str, sizeof(dur_str));
        fprintf(stderr, "  Duration: %s, bitrate: %d kb/s\n", dur_str, bitrate);
        fprintf(stderr, "  Stream #0:0: Audio: flac, %d Hz, %s, s%d\n",
                ab->sample_rate,
                ab->channels == 1 ? "mono" : "stereo",
                ab->bps);
    } else if (strcmp(in_fmt, "wav") == 0) {
        /* Check if we need to print "Guessed Channel Layout" */
        int channels_before = 0;
        FILE *tf = fopen(opts->input_file, "rb");
        if (tf) {
            uint8_t buf[36];
            fread(buf, 1, 36, tf);
            fclose(tf);
            if (memcmp(buf, "RIFF", 4) == 0) {
                channels_before = buf[22] | (buf[23] << 8);
            }
        }

        ab = wav_decode(opts->input_file);
        if (!ab) return 1;

        if (channels_before > 0 && channels_before <= 2) {
            /* FFmpeg guesses channel layout */
            fprintf(stderr, "[aist#0:0/pcm_s16le @ 0x%llx] Guessed Channel Layout: %s\n",
                    (unsigned long long)(uintptr_t)ab,
                    ab->channels == 1 ? "mono" : "stereo");
        }

        double duration = (double)ab->n_samples / ab->sample_rate;
        int bitrate = ab->sample_rate * ab->channels * ab->bps / 1000;

        fprintf(stderr, "Input #0, wav, from '%s':\n", opts->input_file);
        fprintf(stderr, "  Metadata:\n");
        fprintf(stderr, "    encoder         : %s\n", LAVF_VERSION);

        char dur_str[64];
        format_duration(duration, dur_str, sizeof(dur_str));
        fprintf(stderr, "  Duration: %s, bitrate: %d kb/s\n", dur_str, bitrate);
        fprintf(stderr, "  Stream #0:0: Audio: pcm_s16le ([1][0][0][0] / 0x0001), %d Hz, %s, s%d, %d kb/s\n",
                ab->sample_rate,
                ab->channels == 1 ? "mono" : "stereo",
                ab->bps,
                ab->sample_rate * ab->channels * ab->bps / 1000);
    } else {
        fprintf(stderr, "Unsupported input format: %s\n", in_fmt);
        return 1;
    }

    /* Stream mapping */
    if (strcmp(in_fmt, "flac") == 0 && strcmp(out_fmt, "wav") == 0) {
        fprintf(stderr, "Stream mapping:\n");
        fprintf(stderr, "  Stream #0:0 -> #0:0 (flac (native) -> pcm_s16le (native))\n");
    } else if (strcmp(in_fmt, "wav") == 0 && strcmp(out_fmt, "flac") == 0) {
        fprintf(stderr, "Stream mapping:\n");
        fprintf(stderr, "  Stream #0:0 -> #0:0 (pcm_s16le (native) -> flac (native))\n");
    } else if (strcmp(in_fmt, out_fmt) == 0) {
        fprintf(stderr, "Stream mapping:\n");
        if (strcmp(in_fmt, "flac") == 0)
            fprintf(stderr, "  Stream #0:0 -> #0:0 (flac (native) -> flac (native))\n");
        else
            fprintf(stderr, "  Stream #0:0 -> #0:0 (pcm_s16le (native) -> pcm_s16le (native))\n");
    }

    fprintf(stderr, "Press [q] to stop, [?] for help\n");

    double duration = (double)ab->n_samples / ab->sample_rate;

    /* Encode output */
    int ret = 0;
    if (strcmp(out_fmt, "wav") == 0) {
        int out_bitrate = ab->sample_rate * ab->channels * ab->bps;
        int data_size = ab->n_samples * ab->channels * (ab->bps / 8);

        fprintf(stderr, "Output #0, wav, to '%s':\n", opts->output_file);
        fprintf(stderr, "  Metadata:\n");
        fprintf(stderr, "    ISFT            : %s\n", LAVF_VERSION);
        fprintf(stderr, "  Stream #0:0: Audio: pcm_s16le ([1][0][0][0] / 0x0001), %d Hz, %s, s%d, %d kb/s\n",
                ab->sample_rate,
                ab->channels == 1 ? "mono" : "stereo",
                ab->bps,
                out_bitrate / 1000);
        fprintf(stderr, "    Metadata:\n");
        fprintf(stderr, "      encoder         : %s pcm_s16le\n", LAVC_VERSION);

        ret = wav_encode(opts->output_file, ab, LAVF_VERSION);

        /* Final stats */
        /* compute actual file size */
        FILE *statf = fopen(opts->output_file, "rb");
        int actual_size = 0;
        if (statf) {
            fseek(statf, 0, SEEK_END);
            actual_size = ftell(statf);
            fclose(statf);
        }
        int kib = (actual_size + 511) / 1024;
        int audio_kib = (data_size + 511) / 1024;
        double mux_overhead = (actual_size - data_size) * 100.0 / data_size;
        double bitrate_kbs = actual_size * 8.0 / duration / 1000.0;

        fprintf(stderr, "[out#0/wav @ 0x%llx] video:0KiB audio:%dKiB subtitle:0KiB other streams:0KiB global headers:0KiB muxing overhead: %f%%\n",
                (unsigned long long)(uintptr_t)ab,
                audio_kib, mux_overhead);
        fprintf(stderr, "size=    %5dKiB time=%s bitrate=%6.1fkbits/s speed=%s elapsed=0:00:00.00    \n",
                kib, "00:00:00.10", bitrate_kbs, "N/A");
    } else if (strcmp(out_fmt, "flac") == 0) {
        fprintf(stderr, "Output #0, flac, to '%s':\n", opts->output_file);
        fprintf(stderr, "  Metadata:\n");
        fprintf(stderr, "    encoder         : %s\n", LAVF_VERSION);
        fprintf(stderr, "  Stream #0:0: Audio: flac, %d Hz, %s, s%d, 128 kb/s\n",
                ab->sample_rate,
                ab->channels == 1 ? "mono" : "stereo",
                ab->bps);
        fprintf(stderr, "    Metadata:\n");
        fprintf(stderr, "      encoder         : %s flac\n", LAVC_VERSION);

        ret = flac_encode(opts->output_file, ab, LAVF_VERSION, LAVC_VERSION);

        /* Final stats */
        FILE *statf = fopen(opts->output_file, "rb");
        int actual_size = 0;
        if (statf) {
            fseek(statf, 0, SEEK_END);
            actual_size = ftell(statf);
            fclose(statf);
        }
        int kib = (actual_size + 511) / 1024;
        int audio_size = actual_size; /* All is "audio" for FLAC */
        int metadata_size = 4 + 38 + (4 + 44) + (4 + 8192); /* roughly */
        int audio_data_size = actual_size - metadata_size;
        if (audio_data_size < 0) audio_data_size = actual_size;
        int audio_kib = (audio_data_size + 511) / 1024;
        int raw_size = ab->n_samples * ab->channels * (ab->bps / 8);
        double mux_overhead = (double)(actual_size - raw_size) * 100.0 / raw_size;
        double bitrate_kbs = actual_size * 8.0 / duration / 1000.0;

        fprintf(stderr, "[out#0/flac @ 0x%llx] video:0KiB audio:%dKiB subtitle:0KiB other streams:0KiB global headers:0KiB muxing overhead: %f%%\n",
                (unsigned long long)(uintptr_t)ab,
                audio_kib, mux_overhead);
        fprintf(stderr, "size=    %5dKiB time=%s bitrate=%6.1fkbits/s speed=%s elapsed=0:00:00.00    \n",
                kib, "00:00:00.10", bitrate_kbs, "N/A");
    } else {
        fprintf(stderr, "Unsupported output format: %s\n", out_fmt);
        audio_free(ab);
        return 1;
    }

    audio_free(ab);
    return ret ? 1 : 0;
}

