                        ab->channels == 1 ? "mono" : "stereo");

            double duration = (double)ab->n_samples / ab->sample_rate;
            int bitrate = ab->sample_rate * ab->channels * ab->bps / 1000;

            char dur_str[64];
            format_duration(duration, dur_str, sizeof(dur_str));
            fprintf(stderr, "Input #0, wav, from '%s':\n", opts.input_file);
            fprintf(stderr, "  Metadata:\n");
            fprintf(stderr, "    encoder         : %s\n", LAVF_VERSION);
            fprintf(stderr, "  Duration: %s, bitrate: %d kb/s\n", dur_str, bitrate);
            fprintf(stderr, "  Stream #0:0: Audio: pcm_s16le ([1][0][0][0] / 0x0001), %d Hz, %s, s%d, %d kb/s\n",
                    ab->sample_rate,
                    ab->channels == 1 ? "mono" : "stereo",
                    ab->bps,
                    bitrate);
            audio_free(ab);
        }

        fprintf(stderr, "At least one output file must be specified\n");
        return 1;
    }

    return do_convert(&opts);
}

